import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, ClampToEdgeWrapping } = ctx.THREE;

  const group = new Group();
  group.position.set(3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const atlasRect = config.intent?.visualSpec?.atlasRegion ?? { x: 0, y: 0, w: 512, h: 320 };
  const rectW = atlasRect.w ?? 512;
  const rectH = atlasRect.h ?? 320;
  const aspect = rectW / rectH;

  const height = 0.5;
  const width = height * aspect;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff });
  const plane = new Mesh(geometry, material);
  group.add(plane);

  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/feature-card.png';
  ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
    texture.colorSpace = 'srgb';
    texture.wrapS = ClampToEdgeWrapping;
    texture.wrapT = ClampToEdgeWrapping;
    texture.anisotropy = ctx.tier === 'T0' ? 1 : Math.min(4, 4);

    const imgW = texture.image?.width ?? rectW;
    const imgH = texture.image?.height ?? rectH;
    texture.offset.set(atlasRect.x / imgW, atlasRect.y / imgH);
    texture.repeat.set(rectW / imgW, rectH / imgH);

    material.map = texture;
    material.needsUpdate = true;
  });

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  for (const item of items) {
    if (!item || typeof item.text !== 'string' || item.text.length === 0) continue;
    const text = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: colors.paper ?? '#e8ecf2',
      align: 'center'
    });
    text.position.set(0, 0, 0.02);
    group.add(text);
  }

  const timelines = [];

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    for (const t of timelines) {
      if (t && typeof t.kill === 'function') t.kill();
    }
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
  };

  return group;
}
